  // Generated UI buttons are trusted. Only sanitize externally imported HTML, not the workbench controls.
  function modal(title,html,onSave){$('dialog-title').textContent=title;$('dialog-body').innerHTML=html;dialogSave=onSave;$('edit-dialog').showModal();}
  function input(label,id,value,type='text'){return `<label class="field"><span>${E(label)}</span>${type==='textarea'?`<textarea id="${id}">${E(value)}</textarea>`:`<input id="${id}" type="${type}" value="${E(value)}">`}</label>`;}
  function mutate(fn){remember();fn();state.model.config=state.config;C.refresh(state.model);renderResult();saveLocal();}
  function renumber(){if(state.config.autoNumber)state.model.pages.forEach((p,i)=>p.number=`${state.config.chapter}.${state.config.section}.${+state.config.start+i}`);}
  function editPage(index=state.page){const p=state.model.pages[index];if(!p)return;modal('编辑知识页',input('页面标题','edit-title',p.title)+input('副标题','edit-subtitle',p.subtitle)+input('页面说明','edit-description',p.description,'textarea')+`<div class="field-row">${input('页面编号','edit-number',p.number)}${input('文件 slug','edit-slug',p.slug)}</div>`+`<label class="field"><span>本页证明默认状态</span><select id="edit-proof"><option value="inherit">跟随全局规则</option value="closed">折叠</option><option value="open">展开</option></select></label><label class="check"><input id="edit-body-title" type="checkbox"${C.pageConfig(state.model,p).bodyTitle?' checked':''}>本页正文显示标题</label><p class="muted">仅本页规则保存在方案中，不影响其他页面。</p>`,()=>mutate(()=>{p.title=$('edit-title').value;p.subtitle=$('edit-subtitle').value;p.description=$('edit-description').value;p.number=$('edit-number').value;p.slug=C.safeName($('edit-slug').value);p.edited=true;p.rules.bodyTitle=$('edit-body-title').checked;const proof=$('edit-proof').value;if(proof==='inherit')delete p.rules.environments;else p.rules.environments={...C.clone(state.config.environments),proof:{...state.config.environments.proof,collapsed:proof==='closed'}};}));$('edit-proof').value=p.rules.environments?.proof?(p.rules.environments.proof.collapsed?'closed':'open'):'inherit';}
  function editBlock(page,b){const env=!!b.environment;let html=env?`<label class="field"><span>数学环境类型</span><select id="block-env">${Object.entries(state.config.environments).map(([k,e])=>`<option value="${E(k)}"${k===b.environment?' selected':''}>${E(e.label)}</option>`).join('')}</select></label>${input('数学环境标题','block-title',b.title)}<label class="check"><input id="block-collapsed" type="checkbox"${(b.collapsed??state.config.environments[b.environment].collapsed)?' checked':''}>折叠此块</label>`:'';html+=input('此块 TeX（修改后只重新转换这一块）','block-raw',b.raw,'textarea');html+=`<label class="field"><span>移动到页面</span><select id="block-destination">${state.model.pages.map(p=>`<option value="${E(p.id)}"${p.id===page.id?' selected':''}>${E(p.title)}</option>`).join('')}</select></label>`;modal('编辑内容块',html,()=>mutate(()=>{if($('block-raw').value!==b.raw){const next=C.convert([{name:b.file,text:$('block-raw').value}],state.styles,state.config,state.assets);const newBlocks=next.pages.flatMap(p=>p.blocks);page.blocks.splice(page.blocks.indexOf(b),1,...newBlocks.map((n,i)=>({...n,id:b.id+'-edit-'+i,sourceStart:b.sourceStart,sourceEnd:b.sourceEnd,sourceStartLine:b.sourceStartLine,sourceEndLine:b.sourceEndLine})));page.warnings.push(...next.globalWarnings,...next.pages.flatMap(p=>p.warnings));}else{if(env){b.environment=$('block-env').value;b.type=b.environment;b.title=$('block-title').value;b.collapsed=$('block-collapsed').checked;}const dest=state.model.pages.find(p=>p.id===$('block-destination').value);if(dest&&dest!==page){page.blocks.splice(page.blocks.indexOf(b),1);dest.blocks.push(b);}}state.model.layoutEdited=true;}));}
  function jump(file,offset){let i=state.files.findIndex(f=>f.name===file),kind='tex';if(i<0){i=state.styles.findIndex(f=>f.name===file);kind='sty';}if(i<0)return;state.active=kind+':'+i;renderFiles();const input=$('tex-input');input.focus();input.setSelectionRange(offset,Math.min(input.value.length,offset+50));input.scrollTop=(input.value.slice(0,offset).match(/\n/g)||[]).length*22-100;$('line-numbers').scrollTop=input.scrollTop;}
  function unknownRule(name){name=String(name||'').replace(/^\\/,'');modal('手动转换规则 · \\'+name,input('命令或环境名称','unknown-name',name)+`<label class="field"><span>转换方式</span><select id="unknown-mode"><option value="text">替换为安全的普通文本</option><option value="unwrap">保留参数 / 环境正文</option><option value="preserve">保留原文与警告</option></select></label>`+input('替换文本','unknown-text',state.config.unknown[name]?.value||'','textarea'),()=>{remember();const key=$('unknown-name').value.trim().replace(/^\\/,'');if(!/^[A-Za-z@][A-Za-z@*]*$/.test(key))throw Error('请填写有效命令或环境名称');if($('unknown-mode').value==='preserve')delete state.config.unknown[key];else state.config.unknown[key]={mode:$('unknown-mode').value,value:$('unknown-text').value};convertAll(false);});}
