  function uploadFigure(id,dark=false){choose('.svg,image/svg+xml',false,async files=>{if(!files[0])return;const svg=safeSVG(await files[0].text());mutate(()=>applyFigure(id,dark?{darkSvg:svg}:{svg}));});}
  function figureOptions(id){const f=findFigure(id);modal('图形路径、尺寸与说明',input('站内 SVG 路径（可使用 {{root}}）','figure-path',f.path||'')+input('SVG 宽度 px','figure-width',f.width||640,'number')+input('图片说明','figure-caption',f.caption),()=>{const path=$('figure-path').value;if(path&&!/^(?:\{\{root\}\})?[^:<>"']+\.svg$/i.test(path))throw Error('请使用站内 .svg 路径');mutate(()=>applyFigure(id,{path,width:Math.max(80,Math.min(3000,+$('figure-width').value||640)),caption:$('figure-caption').value}));});}
  function localURL(path){const url=new URL(state.config.figure.service);if(!['127.0.0.1','localhost','[::1]'].includes(url.hostname))throw Error('图形服务仅允许本机地址');return new URL(path,url).href;}
  async function checkService(){try{const r=await fetch(localURL('/health'),{signal:AbortSignal.timeout(5000)});if(!r.ok)throw Error('HTTP '+r.status);const data=await r.json();const message=`本地服务已连接 · ${data.engine} · dvisvgm ${data.dvisvgm?'可用':'缺失'}`;if($('compile-state'))$('compile-state').textContent=message;status(message);}catch(e){status('本地服务未连接。运行 node tools/tex2html/server.js 后重试。'+e.message,true);}}
  async function compileFigures(){if(!state.model)return;const figures=state.model.pages.flatMap(p=>p.figures).filter((f,i,a)=>!f.svg&&a.findIndex(x=>x.figureId===f.figureId)===i);if(!figures.length){status('没有待编译的图形。');return;}let token;try{const r=await fetch(localURL('/health'),{signal:AbortSignal.timeout(6000)});const health=await r.json();if(!health.ok)throw Error('本地 xelatex 或 dvisvgm 不可用');token=health.token;}catch(e){status('无法连接本地编译服务：'+e.message,true);return;}remember();let done=0;for(const f of figures){try{status(`本地编译 ${++done}/${figures.length}：${f.figureId}`);const source=C.expand(f.raw,state.model.registry.macros,'math',()=>{}).replace(/\\(?:pp|pause)\b/g,'');const r=await fetch(localURL('/convert/'+(f.kind==='tikz'?'tikz':'xypic')),{method:'POST',headers:{'Content-Type':'application/json','X-Tex2HTML-Token':token},body:JSON.stringify({source,options:state.config.figure}),signal:AbortSignal.timeout(150000)});const result=await r.json();if(!r.ok)throw Error(result.error+(result.log?'\n'+result.log:''));applyFigure(f.figureId,{svg:safeSVG(result.svg),darkSvg:result.darkSvg?safeSVG(result.darkSvg):null});state.model.log.push(...(result.warnings||[]),`已编译 ${f.figureId}`);}catch(e){state.model.log.push(`${f.figureId} 编译失败：${e.message}`);for(const page of state.model.pages){if(page.figures.some(x=>x.figureId===f.figureId))page.warnings.push({file:f.file,line:f.sourceStartLine,offset:f.sourceStart,command:f.kind,raw:f.raw,reason:e.message,suggestion:'查看日志，或上传已生成的 SVG。',severity:'error'});}}renderResult();}saveLocal();status('图形编译结束。失败项保留源码，可在警告和日志中查看原因。');}
  function addMacro(){modal('添加自定义命令',input('名称（不含反斜杠）','macro-name','')+input('参数个数（0–9）','macro-args',0,'number')+input('展开结果（使用 #1、#2 表示参数）','macro-value','','textarea'),()=>{const name=$('macro-name').value.replace(/^\\/,'').trim();if(!/^[A-Za-z@]+$/.test(name))throw Error('命令名称只能包含英文字母或 @');remember();state.config.macros[name]={name,body:$('macro-value').value,defaultBody:$('macro-value').value,args:Math.max(0,Math.min(9,+$('macro-args').value||0)),optional:null,enabled:true,scope:'all',source:'手动规则',line:1,unsafe:''};convertAll(false);});}
